CREATE TABLE admin_users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(24) NOT NULL DEFAULT 'ADMIN', active BOOLEAN NOT NULL DEFAULT TRUE, failed_logins INT NOT NULL DEFAULT 0, locked_until TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contact_messages (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, subject VARCHAR(180) NOT NULL, message TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'NEW', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_message_status_created(status,created_at));
CREATE TABLE message_notes (id BIGINT PRIMARY KEY AUTO_INCREMENT, message_id BIGINT NOT NULL, admin_user_id BIGINT NOT NULL, note TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_note_message FOREIGN KEY(message_id) REFERENCES contact_messages(id) ON DELETE CASCADE, CONSTRAINT fk_note_admin FOREIGN KEY(admin_user_id) REFERENCES admin_users(id));
CREATE TABLE newsletter_subscribers (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL UNIQUE, subscribed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE products (id BIGINT PRIMARY KEY AUTO_INCREMENT, type VARCHAR(16) NOT NULL, name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, tagline VARCHAR(220) NOT NULL, short_description VARCHAR(500) NOT NULL, long_description TEXT, category VARCHAR(100), status VARCHAR(24) NOT NULL DEFAULT 'IN_DEVELOPMENT', featured BOOLEAN NOT NULL DEFAULT FALSE, accent_color VARCHAR(7) NOT NULL DEFAULT '#146c66', logo_url VARCHAR(500), cover_url VARCHAR(500), tech_stack JSON, public_url VARCHAR(500), client_name VARCHAR(180), project_year INT, display_order INT NOT NULL DEFAULT 0, published BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_products_listing(published, type, display_order));
CREATE TABLE product_translations (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, language VARCHAR(5) NOT NULL, tagline VARCHAR(220) NOT NULL, short_description VARCHAR(500) NOT NULL, long_description TEXT, UNIQUE KEY uq_product_language(product_id,language), CONSTRAINT fk_translation_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE media (id BIGINT PRIMARY KEY AUTO_INCREMENT, original_name VARCHAR(255) NOT NULL, storage_key VARCHAR(500) NOT NULL UNIQUE, content_type VARCHAR(100) NOT NULL, size_bytes BIGINT NOT NULL, width INT, height INT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_images (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, media_id BIGINT, image_url VARCHAR(500) NOT NULL, alt_text VARCHAR(250) NOT NULL, display_order INT NOT NULL DEFAULT 0, CONSTRAINT fk_image_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, CONSTRAINT fk_image_media FOREIGN KEY(media_id) REFERENCES media(id) ON DELETE SET NULL);
CREATE TABLE statistics (id BIGINT PRIMARY KEY AUTO_INCREMENT, label VARCHAR(80) NOT NULL, value INT NOT NULL DEFAULT 0, suffix VARCHAR(12) NOT NULL DEFAULT '+', display_order INT NOT NULL DEFAULT 0, visible BOOLEAN NOT NULL DEFAULT FALSE);

